//! Exact native-generated bytes exercise strict storage reconstruction.
//! Copied fixture DATA supplies no native author/receiver capability.
use super::*;
use std::time::SystemTime;

struct NativeCuts {
    root: sinomo_testdir::TestDir,
    shard: DfsMetadataShardId,
    base: crate::DfsMetadataPrefixProof,
    complete: crate::DfsMetadataPrefixProof,
    created: DfsObjectMetadata,
    suffix: Vec<(DfsMetadataJournalEntry, Vec<u8>)>,
}

fn copy_files(source: &Path, target: &Path) {
    fs::create_dir_all(target).unwrap();
    for entry in fs::read_dir(source).unwrap() {
        let path = entry.unwrap().path();
        let to = target.join(path.file_name().unwrap());
        let metadata = fs::symlink_metadata(&path).unwrap();
        assert!(!metadata.file_type().is_symlink());
        if metadata.is_dir() {
            copy_files(&path, &to);
        } else {
            assert!(metadata.is_file());
            fs::copy(&path, &to).unwrap();
            assert_eq!(fs::read(&path).unwrap(), fs::read(to).unwrap());
        }
    }
}

fn native_cuts(name: &str) -> NativeCuts {
    let (runtime, mut service, config) = native_case(name, 1);
    directory(&mut service, "/services/cursor-base");
    let shard = DfsMetadataShardId::new(&config.shard_id);
    let source =
        crate::local_dfs_metadata_shard_path(runtime.data_dir(&config.primary_node_id), &shard);
    let root = sinomo_testdir::TestDir::new(&format!("{name}-storage-cut"));
    let base = {
        let mut inspection =
            LocalSobjMetadataBackend::open_for_inspection(shard.clone(), &source).unwrap();
        let _fence = inspection.metadata_write_lock().unwrap();
        inspection.begin_inspection_snapshot().unwrap();
        let prefix = inspection.metadata_prefix_proof().unwrap();
        assert!(prefix.journal_sequence > 1 && prefix.journal_sequence < 512);
        copy_files(&source, root.path());
        prefix
    };
    let created = directory(&mut service, "/services/cursor-real-suffix");
    let (complete, suffix) = {
        let mut inspection =
            LocalSobjMetadataBackend::open_for_inspection(shard.clone(), &source).unwrap();
        let _fence = inspection.metadata_write_lock().unwrap();
        inspection.begin_inspection_snapshot().unwrap();
        let complete = inspection.metadata_prefix_proof().unwrap();
        let entries = crate::metadata_journal::durable_journal_entries_since_limited(
            &source,
            base.journal_sequence,
            64,
        )
        .unwrap();
        assert!(!entries.is_empty() && entries.len() < 64);
        assert_eq!(entries.first().unwrap().sequence, base.journal_sequence + 1);
        assert_eq!(entries.last().unwrap().sequence, complete.journal_sequence);
        let frames = crate::metadata_journal::read_segmented_journal_frames_at_sequences(
            &source,
            &entries
                .iter()
                .map(|entry| entry.sequence)
                .collect::<Vec<_>>(),
        )
        .unwrap();
        let suffix = entries
            .into_iter()
            .zip(frames)
            .map(|(entry, frame)| {
                let frame = frame.expect("actual native suffix frame");
                assert_eq!(frame.entry(), &entry);
                (entry, frame.exact_bytes().to_vec())
            })
            .collect();
        (complete, suffix)
    };
    drop(service);
    runtime.close().unwrap();
    NativeCuts {
        root,
        shard,
        base,
        complete,
        created,
        suffix,
    }
}

#[derive(Debug, Eq, PartialEq)]
struct FileObservation {
    bytes: Vec<u8>,
    modified: SystemTime,
    identity: (u64, u64),
}

fn file(path: &Path) -> FileObservation {
    let handle = fs::File::open(path).unwrap();
    let metadata = handle.metadata().unwrap();
    assert!(metadata.is_file());
    FileObservation {
        bytes: fs::read(path).unwrap(),
        modified: metadata.modified().unwrap(),
        identity: crate::runtime_host::storage_file_identity(&handle).unwrap(),
    }
}

fn files(root: &Path) -> BTreeMap<PathBuf, FileObservation> {
    let mut pending = vec![root.to_owned()];
    let mut result = BTreeMap::new();
    let mut size = 0usize;
    while let Some(directory) = pending.pop() {
        for entry in fs::read_dir(directory).unwrap() {
            let path = entry.unwrap().path();
            let metadata = fs::symlink_metadata(&path).unwrap();
            assert!(!metadata.file_type().is_symlink());
            if metadata.is_dir() {
                pending.push(path);
            } else {
                size = size
                    .checked_add(usize::try_from(metadata.len()).unwrap())
                    .unwrap();
                assert!(
                    result.len() < 256 && size < 8 * 1024 * 1024,
                    "bounded physical shard inventory"
                );
                result.insert(path.strip_prefix(root).unwrap().to_owned(), file(&path));
            }
        }
    }
    result
}

fn write_hint(root: &Path, shard: &DfsMetadataShardId, sequence: u64) {
    let _fence = crate::metadata_lock::metadata_write_lock(
        root.to_owned(),
        crate::metadata_cursor::journal_write_lock_path(root),
    )
    .unwrap();
    crate::metadata_cursor::write_local_materialization_cursor(
        root,
        &crate::metadata_journal::DfsMetadataReplayCursor {
            shard_id: shard.clone(),
            last_sequence: sequence,
        },
    )
    .unwrap();
}

#[test]
fn strict_reopen_preserves_lagging_local_cursor_and_all_existing_bytes() {
    let cut = native_cuts("strict-local-cursor-idle");
    // This negative scheduling hint cannot change the real native table cut.
    write_hint(cut.root.path(), &cut.shard, cut.base.journal_sequence - 1);
    let before = files(cut.root.path());
    for _ in 0..3 {
        let backend = LocalSobjMetadataBackend::new(cut.shard.clone(), cut.root.path()).unwrap();
        assert_eq!(backend.metadata_prefix_proof().unwrap(), cut.base);
        assert_eq!(
            backend
                .local_materialization_cursor()
                .unwrap()
                .last_sequence,
            cut.base.journal_sequence - 1
        );
        drop(backend);
        assert_eq!(
            files(cut.root.path()),
            before,
            "unchanged strict reconstruction must not rewrite any existing owned file"
        );
    }
}

#[test]
fn strict_reopen_recovers_actual_native_suffix_then_preserves_the_settled_cut() {
    let cut = native_cuts("strict-local-cursor-suffix");
    write_hint(cut.root.path(), &cut.shard, 0);
    {
        let _fence = crate::metadata_lock::metadata_write_lock(
            cut.root.path().to_owned(),
            crate::metadata_cursor::journal_write_lock_path(cut.root.path()),
        )
        .unwrap();
        // Model only the real journal-durable/table-lagging storage cut by
        // appending EXACT later native bytes. No body/ID/guard is invented.
        crate::metadata_journal::append_segmented_journal_exact_frames(
            cut.root.path(),
            &cut.suffix
                .iter()
                .map(|(entry, bytes)| (entry, bytes.as_slice()))
                .collect::<Vec<_>>(),
            0,
        )
        .unwrap();
    }
    let frames_before = crate::metadata_journal::read_segmented_journal_frames_at_sequences(
        cut.root.path(),
        &cut.suffix
            .iter()
            .map(|(entry, _)| entry.sequence)
            .collect::<Vec<_>>(),
    )
    .unwrap()
    .into_iter()
    .map(|frame| frame.unwrap().exact_bytes().to_vec())
    .collect::<Vec<_>>();
    assert_eq!(
        frames_before,
        cut.suffix
            .iter()
            .map(|(_, bytes)| bytes.clone())
            .collect::<Vec<_>>()
    );
    let inspection =
        LocalSobjMetadataBackend::open_for_inspection(cut.shard.clone(), cut.root.path()).unwrap();
    assert_eq!(
        inspection.metadata_prefix_proof().unwrap(),
        cut.base,
        "prerequisite: actual table cut still precedes durable suffix"
    );
    drop(inspection);
    let backend = LocalSobjMetadataBackend::new(cut.shard.clone(), cut.root.path()).unwrap();
    assert_eq!(backend.metadata_prefix_proof().unwrap(), cut.complete);
    assert_eq!(
        backend
            .get_object_by_path(&cut.created.file_system_id, &cut.created.path)
            .unwrap(),
        Some(cut.created.clone())
    );
    assert_eq!(
        backend
            .local_materialization_cursor()
            .unwrap()
            .last_sequence,
        cut.complete.journal_sequence,
        "actual suffix recovery still persists its real progress"
    );
    drop(backend);
    let settled = files(cut.root.path());
    let reopened = LocalSobjMetadataBackend::new(cut.shard.clone(), cut.root.path()).unwrap();
    assert_eq!(reopened.metadata_prefix_proof().unwrap(), cut.complete);
    drop(reopened);
    assert_eq!(files(cut.root.path()), settled);
    let frames_after = crate::metadata_journal::read_segmented_journal_frames_at_sequences(
        cut.root.path(),
        &cut.suffix
            .iter()
            .map(|(entry, _)| entry.sequence)
            .collect::<Vec<_>>(),
    )
    .unwrap()
    .into_iter()
    .map(|frame| frame.unwrap().exact_bytes().to_vec())
    .collect::<Vec<_>>();
    assert_eq!(
        frames_after, frames_before,
        "real replay never rewrites original canonical frames"
    );
}

#[test]
fn strict_reopen_keeps_missing_hint_initialization_and_ahead_hint_rewind() {
    let cut = native_cuts("strict-local-cursor-init-ahead");
    let cursor = crate::metadata_cursor::local_materialization_cursor_path(cut.root.path());
    fs::remove_file(&cursor).unwrap();
    let backend = LocalSobjMetadataBackend::new(cut.shard.clone(), cut.root.path()).unwrap();
    assert_eq!(backend.metadata_prefix_proof().unwrap(), cut.base);
    assert_eq!(
        backend
            .local_materialization_cursor()
            .unwrap()
            .last_sequence,
        cut.base.journal_sequence
    );
    assert!(cursor.is_file());
    drop(backend);
    write_hint(cut.root.path(), &cut.shard, cut.base.journal_sequence + 7);
    let ahead = file(&cursor);
    let backend = LocalSobjMetadataBackend::new(cut.shard.clone(), cut.root.path()).unwrap();
    assert_eq!(backend.metadata_prefix_proof().unwrap(), cut.base);
    assert_eq!(
        backend
            .local_materialization_cursor()
            .unwrap()
            .last_sequence,
        cut.base.journal_sequence
    );
    drop(backend);
    assert_ne!(file(&cursor).bytes, ahead.bytes);
    let settled = files(cut.root.path());
    drop(LocalSobjMetadataBackend::new(cut.shard.clone(), cut.root.path()).unwrap());
    assert_eq!(files(cut.root.path()), settled);
}

#[test]
fn strict_reopen_refuses_corrupt_foreign_hint_and_missing_canonical_source() {
    let cut = native_cuts("strict-local-cursor-invalid");
    let cases = sinomo_testdir::TestDir::new("strict-local-cursor-invalid-copies");
    for variant in ["corrupt", "foreign", "missing-frame"] {
        let root = cases.join(variant);
        copy_files(cut.root.path(), &root);
        let cursor = crate::metadata_cursor::local_materialization_cursor_path(&root);
        match variant {
            "corrupt" => fs::write(&cursor, b"incomplete SOBJ cursor").unwrap(),
            "foreign" => write_hint(&root, &DfsMetadataShardId::new("foreign-cursor-scope"), 0),
            "missing-frame" => {
                let segments = fs::read_dir(root.join("journal/segments"))
                    .unwrap()
                    .map(|entry| entry.unwrap().path())
                    .filter(|path| {
                        path.extension()
                            .is_some_and(|extension| extension == "slog")
                    })
                    .collect::<Vec<_>>();
                assert_eq!(
                    segments.len(),
                    1,
                    "small genuine native fixture has one required canonical segment"
                );
                fs::remove_file(&segments[0]).unwrap();
            }
            _ => unreachable!(),
        }
        let before = file(&cursor);
        let error = LocalSobjMetadataBackend::new(cut.shard.clone(), &root)
            .expect_err("invalid hint or missing canonical bytes cannot become ready");
        if variant == "foreign" {
            assert!(
                error.to_string().contains("foreign metadata shard"),
                "{error}"
            );
        }
        assert_eq!(
            file(&cursor),
            before,
            "refusal must not silently replace the rejected scheduling hint"
        );
    }
}
